#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdlib>
using namespace std;

struct AbsCompare {
    bool operator()(int a, int b) const {
        return abs(a) < abs(b);
    }
};

int main() {
    vector<int> v = {-3, 1, -2, 5, -4};
    sort(v.begin(), v.end(), AbsCompare());
    for (int x : v) cout << x << " ";
    cout << endl;
    return 0;
}
